function purgeEverything() {
  if (state.purging) return;
  var loadedKeys = allRows.filter(function (r) { return r.data_status === 'data_loaded'; }).map(function (r) { return r.source_key; });
  if (!loadedKeys.length) { showMessage('info', 'No leaf nodes with data to purge.'); return; }
  var count = loadedKeys.length;
  var list = loadedKeys.map(function (k) {
    return '<div style="padding:6px 10px;border-radius:6px;background:rgba(128,128,128,.12);font-size:13px;margin-top:6px;">' + esc(k) + '</div>';
  }).join('');
  var m = createModal(
    '<div style="font-size:18px;font-weight:600;">Purge all leaf node data?</div>' +
    '<div style="opacity:.75;font-size:13px;margin-top:6px;">This will remove data for all ' + count + ' loaded leaf node' + (count === 1 ? '' : 's') + '.</div>' +
    '<div style="max-height:200px;overflow-y:auto;margin:14px 0 18px;">' + list + '</div>' +
    '<div style="display:flex;justify-content:flex-end;gap:8px;">' +
    '<button id="h3r-purge-cancel" style="' + MODAL_BTN + '">Cancel</button>' +
    '<button id="h3r-purge-confirm" style="' + MODAL_BTN + MODAL_DANGER + '">Yes, purge everything</button></div>'
  );
