    h += '<button data-page="' + i + '" style="width:26px;height:26px;display:flex;align-items:center;justify-content:center;border-radius:4px;border:none;font-size:12px;font-weight:600;cursor:pointer;' + (active ? 'background:#3b82f6;color:#fff;' : 'background:transparent;color:#4b5563;') + '">' + i + '</button>';
